window.SIM_DATA = {"id":"lab-bgp","w":1242,"h":1060,"images":["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"],"slides":[{"img":0,"step":"Introduction","text":"Lab BGP – CR (client) relié à ISP1 (AS 100), lui-même en eBGP avec ISP2 (AS 200). Écrans reconstitués : résultats attendus.","kind":"show","dur":10880},{"img":1,"step":"Étape 1 · Config de base","text":"Configuration de base du routeur client : nommez-le CR.","kind":"type","x":127.0,"answers":["hostname CR"]},{"img":2,"step":"Étape 1 · Config de base","text":"LAN F0/0 = 192.168.1.1/24 déjà fait. Adressez S1/0 vers ISP1.","kind":"type","x":119.0,"answers":["ip address 10.10.10.1 255.255.255.0","ip add 10.10.10.1 255.255.255.0"]},{"img":3,"step":"Étape 1 · Config de base","text":"ISP1 : S1/0 10.10.10.2, S1/1 172.16.1.1, Loopback0 192.168.100.1/24. ISP2 : S1/0 172.16.1.2, Loopback0 192.168.200.1/24.","kind":"show","dur":10700},{"img":4,"step":"Étape 1 · Config de base","text":"Adressez l'hôte client : IP, masque et passerelle.","kind":"type","x":48.0,"answers":["ip 192.168.1.10 255.255.255.0 192.168.1.1","ip 192.168.1.10 /24 192.168.1.1","ip 192.168.1.10/24 192.168.1.1"]},{"img":5,"step":"Étape 1 · Config de base","text":"Test 1.c : CR peut-il joindre ISP2 ?","kind":"type","x":33.0,"answers":["ping 172.16.1.2"]},{"img":6,"step":"Étape 1 · Config de base","text":"Non : CR ne connaît que ses réseaux directement connectés, aucune route vers 172.16.1.0/24.","kind":"show","dur":8960},{"img":7,"step":"Étape 1 · Config de base","text":"L'hôte peut-il joindre ISP1 ?","kind":"type","x":48.0,"answers":["ping 10.10.10.2"]},{"img":8,"step":"Étape 1 · Config de base","text":"Non : ISP1 n'a pas de route de retour vers 192.168.1.0/24.","kind":"show","dur":6980},{"img":9,"step":"Étape 2 · Routes statiques","text":"Route par défaut de CR vers ISP1 (site à une seule sortie).","kind":"type","x":96.0,"answers":["ip route 0.0.0.0 0.0.0.0 10.10.10.2"]},{"img":10,"step":"Étape 2 · Routes statiques","text":"Sur ISP1, route statique de retour vers le LAN du client.","kind":"type","x":111.0,"answers":["ip route 192.168.1.0 255.255.255.0 10.10.10.1"]},{"img":11,"step":"Étape 2 · Routes statiques","text":"Refaites le ping de l'hôte vers ISP1.","kind":"type","x":48.0,"answers":["ping 10.10.10.2"]},{"img":12,"step":"Étape 2 · Routes statiques","text":"Succès (TTL 254 : un routeur traversé).","kind":"show","dur":6000},{"img":13,"step":"Étape 3 · BGP","text":"Sur ISP1, démarrez BGP dans l'AS 100.","kind":"type","x":111.0,"answers":["router bgp 100"]},{"img":14,"step":"Étape 3 · BGP","text":"Déclarez ISP2 comme voisin eBGP (AS 200 ≠ 100).","kind":"type","x":166.0,"answers":["neighbor 172.16.1.2 remote-as 200"]},{"img":15,"step":"Étape 3 · BGP","text":"Annoncez le réseau du client (présent dans la table grâce à la route statique).","kind":"type","x":166.0,"answers":["network 192.168.1.0","network 192.168.1.0 mask 255.255.255.0"]},{"img":16,"step":"Étape 3 · BGP","text":"Après la configuration symétrique sur ISP2 (AS 200, réseau 192.168.200.0) : session eBGP Up.","kind":"show","dur":9020},{"img":17,"step":"Étape 4 · Tables de routage","text":"Affichez la table de routage d'ISP2.","kind":"type","x":48.0,"answers":["show ip route","sh ip route","sh ip ro"]},{"img":18,"step":"Étape 4 · Tables de routage","text":"192.168.1.0 présent avec la lettre B = appris par BGP (eBGP, DA 20), annoncé par ISP1 (172.16.1.1).","kind":"show","dur":9440},{"img":19,"step":"Étape 4 · Tables de routage","text":"Affichez la table de routage de CR.","kind":"type","x":33.0,"answers":["show ip route","sh ip route","sh ip ro"]},{"img":20,"step":"Étape 4 · Tables de routage","text":"Pas de 192.168.100.0 ni 192.168.200.0 : CR ne fait pas de BGP, sa route par défaut S* lui suffit.","kind":"show","dur":9320},{"img":21,"step":"Étapes 5–6 · Tests et table BGP","text":"Depuis l'hôte, pinguez la Loopback0 d'ISP2.","kind":"type","x":48.0,"answers":["ping 192.168.200.1"]},{"img":22,"step":"Étapes 5–6 · Tests et table BGP","text":"Succès : aller via la route par défaut puis BGP, retour via BGP puis la route statique d'ISP1.","kind":"show","dur":9140},{"img":23,"step":"Étapes 5–6 · Tests et table BGP","text":"Affichez la table BGP d'ISP1.","kind":"type","x":48.0,"answers":["show ip bgp","sh ip bgp"]},{"img":24,"step":"Étapes 5–6 · Tests et table BGP","text":"*> = meilleure route. Weight 32768 = réseau local. Path « 200 i » = appris de l'AS 200 par une commande network.","kind":"show","dur":10220},{"img":25,"step":"Fin","text":"eBGP entre FAI (AS 100 ↔ AS 200) et routage statique côté client : connectivité de bout en bout validée.","kind":"show","dur":9740}]};
